const download=require("download"),fse=require("fs-extra"),path=require("path"),promiseMap={};async function downloadLargeFile(e,o){console.log("[downloadLargeFile]",e,o);try{if(promiseMap[e])return promiseMap[e];fse.ensureDirSync(path.dirname(o));const a=(new Date).getTime(),l=download(e);promiseMap[e]=l,fse.writeFileSync(o,await l),console.log(`[downloadLargeFile]download finish ${o}. cost: ${(new Date).getTime()-a}ms`)}catch(o){throw console.log(`download file fail: ${e}`,o),o}finally{delete promiseMap[e]}}module.exports={downloadLargeFile:downloadLargeFile};